import logo from './logo.svg';
import './App.css';

function Welcome(props) {
  return <h1 className="App-logo">Hello, {props.name}</h1>;
}
let x=100;
function App(props) {
  return (
    <div className="App-logo">
      <header className="App-header">

        <p>
        {x}  lien {props.y} 
        <Welcome name="Sara" />
        <Welcome name="Cahal" />
        <Welcome name="Edite" />
        </p>
        <a
          className="App-link"
          href="{props.y}"
          target="_blank"
          rel="noopener noreferrer"
        >
          {props.y}
        </a>
      </header>
    </div>
  );
}

export default App;
